scaler.text:
def fit_scaler(X: pd.DataFrame) -> StandardScaler:
    """K-Means는 유클리드 거리를 쓰므로 단위가 큰 변수(소득, 만원)가 거리를 독차지하지 않게 표준화한다."""
    return StandardScaler().fit(X[FEATURES])

